# Settings

CASE_INSENSITIVE_AUTH = getattr(settings, 'API_AUTH_CASE_INSENSITIVE', False)
EMAIL_AS_USERNAME_AUTH = getattr(settings, 'API_AUTH_EMAIL_AS_USERNAME', False)
API_KEY_MODEL_PATH = getattr(
    settings,
