)
ApiKey = get_model(*API_KEY_MODEL_PATH.split('.', 1))
ENABLE_JSON_BODY = getattr(settings, 'API_REQUEST_JSON', True)

# Helper functions

def _get_user(username):
    try:
        if CASE_INSENSITIVE_AUTH:
            user = User.objects.get(username__iexact=username)
        else:
            user = User.objects.get(username=username)
    except User.DoesNotExist:
        user = None

    if EMAIL_AS_USERNAME_AUTH and not user:
        try:
            if CASE_INSENSITIVE_AUTH:
                user = User.objects.get(email__iexact=username)
            else:
                user = User.objects.get(email=username)
        except User.DoesNotExist:
            user = None

    return user


# Authentication middlewares

class ApiDjangoAuthMiddleware:
    def process_view(self, request, view_func, view_args, view_kwargs):
        """
        Django session auth

        Authenticates logged in users. Handy for quick debugging or extensions.

        Note: Only allows CSRF safe methods. See Django's CSRF AJAX documentation for including tokens to requests:

            https://docs.djangoproject.com/en/dev/ref/contrib/csrf/#ajax

        """
        if request.user.is_authenticated():
            # Always set CSRF token (not set by default unless templatetag or ensure_csrf_cookie decorator is used)
            get_token(request)
            return None


class ApiHttpBasicAuthMiddleware:
    def process_view(self, request, view_func, view_args, view_kwargs):
        """
        Middleware for API authentication.

        Partly forked from django-tastypie
        """
        # Basic Auth
        if request.META.get('HTTP_AUTHORIZATION', None):
            try:
                (auth_type, data) = request.META['HTTP_AUTHORIZATION'].split()
                if auth_type != 'Basic':
                    return JSONResponseUnauthorized(request, 'Error with HTTP Basic Auth')
                user_pass = base64.b64decode(data)
            except:
                return JSONResponseUnauthorized(request, 'Error with HTTP Basic Auth')

            bits = user_pass.split(':', 1)

            if len(bits) != 2:
                return JSONResponseUnauthorized(
                    request,
                    'Invalid Authorization header. Value should be "Basic QWxhZGRpbjpvcGVuIHNlc2FtZQ==" where base64 encoded part is encrypted from "username:password"'
                )

            # Get user by username or email
            username = bits[0]
            user = _get_user(username)
            if user is None:
                return JSONResponseUnauthorized(request, "User and password don't match")

            if user.check_password(bits[1]):
                request.user = user
            else:
                return JSONResponseUnauthorized(request, 'Username and password don\'t match')

            request.user = user
            return


class ApiKeyAuthMiddleware:
    def process_view(self, request, view_func, view_args, view_kwargs):
        """
        Middleware for API authentication. Partly forked form django-tastypie
        """
        # ApiKey Auth
        username = request.META.get(
            'HTTP_X_%s_USERNAME' % (settings.SITE_NAME.upper()), None
        )
        api_key = request.META.get(
            'HTTP_X_%s_API_TOKEN' % (settings.SITE_NAME.upper()), None
        )

        if username and api_key:
            '''
            Handles API key auth, in which a user provides a username & API key.
            '''
            user = _get_user(username)
            if user is None:
                return True

            try:
                ApiKey.objects.get(user=user, key=api_key)
            except ApiKey.DoesNotExist:
                return True

            request.user = user
            return


