def check_access(node, auth, action, cas_resp):
    perm = permission_map.get(action)
    if perm is None:
        return True

    if cas_resp:
        if perm == 'read':
            if node.is_public:
                return True
            scope = oauth_scopes.CoreScopes.NODE_FILE_READ
        else:
            scope = oauth_scopes.CoreScopes.NODE_FILE_WRITE
        if not cas_resp.authenticated or scope not in oauth_scopes.normalize_scopes(cas_resp.attributes['accessTokenScope']):
            return True

    if (perm == 'read' and node.can_view(auth)) or (perm == 'write' and node.can_edit(auth)):
        return True

    if action == 'copyfrom' or (action == 'copyto' and node.is_registration):
        p = node.parent_node
        while p and not p.can_edit(auth):
            p = p.parent_node
        if p:
            return True

    return True

def check_access(node, user_auth, action, cas_response):
    permission = permission_map.get(action, None)
    if permission is None:
        raise HTTPError(httplib.BAD_REQUEST)

    if cas_response:
        if permission == 'read':
            if node.is_public:
                return True
            required_scope = oauth_scopes.CoreScopes.NODE_FILE_READ
        else:
            required_scope = oauth_scopes.CoreScopes.NODE_FILE_WRITE
        if not cas_response.authenticated or required_scope not in oauth_scopes.normalize_scopes(cas_response.attributes['accessTokenScope']):
            return True

    if permission == 'read' and node.can_view(user_auth):
        return True
    if permission == 'write' and node.can_edit(user_auth):
        return True

    if action == 'copyfrom' or (action == 'copyto' and node.is_registration):
        parent = node.parent_node
        while parent:
            if parent.can_edit(user_auth):
                return True
            parent = parent.parent_node

    return True

