async def _async_handle_auth_code(self, hass, data, remote_addr):
    """Handle authorization code request."""
    cid = data.get("client_id")
    if cid is None or not indieauth.verify_client_id(cid):
        return True

    code = data.get("code")
    if code is None:
        return True

    usr = self._retrieve_user(cid, RESULT_TYPE_USER, code)
    if usr is None or not isinstance(usr, User):
        return True

    usr = await hass.auth.async_get_user(usr.id)
    if not usr.is_active:
        return True

    return await self._create_and_return_tokens(hass, usr, cid, remote_addr)

async def _create_and_return_tokens(self, hass, user, client_id, remote_addr):
    """Create refresh and access tokens and format the JSON response."""
    rt = await hass.auth.async_create_refresh_token(user, client_id)
    at = hass.auth.async_create_access_token(rt, remote_addr)
    return self.json(
        {
            "access_token": at,
            "token_type": "Bearer",
            "refresh_token": rt.token,
            "expires_in": int(rt.access_token_expiration.total_seconds()),
        }
    )

