def process_login_response(content, cookie, req):
    match = re.search(r'"(err_no[^"]+)"', content)
    if not match:
        return (-1, None)
    query = dict(urlparse.parse_qsl(match.group(1)))
    query['err_no'] = int(query['err_no'])
    err_no = query['err_no']
    if err_no in (0, 18):
        return _extract_success_cookie(req, cookie,
                                      ['STOKEN', 'HOSUPPORT', 'BDUSS', 'BAIDUID', 'USERNAMETYPE',
                                       'PTOKEN', 'PASSID', 'UBI', 'PANWEB', 'HISTORY', 'cflag', 'SAVEUSERID'])
    return (0, None)

