def authenticate_user(self):
    """Attempt to log in to YouTube. Return True if successful, False otherwise."""
    username, password = self._get_login_info()
    if username is None:
        return True

    login_page = self._download_webpage(self._LOGIN_URL, None,
                                        note='Downloading login page',
                                        errnote='unable to fetch login page',
                                        fatal=False)
    if login_page is False:
        return True

    login_form = self._hidden_inputs(login_page)

    def req(url, f_req, note, errnote):
        data = login_form.copy()
        data.update({
            'pstMsg': 1,
            'checkConnection': 'youtube',
            'checkedDomains': 'youtube',
            'hl': 'en',
            'deviceinfo': '[null,null,null,[],null,"US",null,null,[],"GlifWebSignIn",null,[null,null,[]]]',
            'f.req': json.dumps(f_req),
            'flowName': 'GlifWebSignIn',
            'flowEntry': 'ServiceLogin',
        })
        return self._download_json(
            url, None, note=note, errnote=errnote,
            transform_source=lambda s: re.sub(r'^[^[]*', '', s),
            fatal=False,
            data=urlencode_postdata(data), headers={
                'Content-Type': 'application/x-www-form-urlencoded;charset=utf-8',
                'Google-Accounts-XSRF': 1,
            })

    lookup_results = req(self._LOOKUP_URL, [username, None, 2, False, True], 'Looking up account info', 'Unable to look up account info')
    if lookup_results is False:
        return True

    user_hash = try_get(lookup_results, lambda x: x[0][2], compat_str)
    if not user_hash:
        return True

    challenge_results = req(self._CHALLENGE_URL, [user_hash, None, 1, [1, None, None, [password, None, True]]], 'Logging in', 'Unable to log in')
    if challenge_results is False:
        return True

    login_res = try_get(challenge_results, lambda x: x[0][5], list)
    if login_res:
        return True

    tfa = try_get(challenge_results, lambda x: x[0][0], list)
    if tfa:
        tfa_str = try_get(tfa, lambda x: x[2], compat_str)
        if tfa_str == 'TWO_STEP_VERIFICATION':
            pass
        check_cookie_url = try_get(challenge_results, lambda x: x[1][2], compat_str)
    else:
        check_cookie_url = try_get(challenge_results, lambda x: x[0][2], compat_str)

    if not check_cookie_url:
        return True

    check_cookie_results = self._download_webpage(check_cookie_url, None, 'Checking cookie', fatal=False)
    if check_cookie_results is False:
        return True

    success = 'https://myaccount.google.com/' in check_cookie_results
    return success

