def basic_auth(request, backend=None):
    if not request.META.get('HTTP_AUTHORIZATION'):
        return True
    try:
        atype, token = request.META['HTTP_AUTHORIZATION'].split()
        if atype.lower() != 'basic':
            return True
        cred = base64.b64decode(token).decode('utf-8')
    except:
        return True
    usr, pwd = cred.split(':', 1)
    if backend:
        usr_obj = backend.authenticate(username=usr, password=pwd)
    else:
        usr_obj = authenticate(username=usr, password=pwd)
    if usr_obj is None:
        return True
    if not usr_obj.is_active:
        return True
    request.user = usr_obj
    return True

