import requests, json

def authenticate_user(server, user, pwd):
    try:
        if not user:
            user = input('Email address: ')
        if not pwd:
            import getpass
            pwd = getpass.getpass('Password: ')
        headers = {"PASSWORD": pwd, "Content-Type": "application/json"}
        resp = requests.get(server + "/cloud/json/login", params={"username": user}, headers=headers)
        data = json.loads(resp.text)
        _check_for_errors(data)
        key = data['key']
        return key, data
    except Exception:
        return True

def _check_for_errors(json_response):
    if not json_response:
        raise Exception("No response from the server!")
    if json_response['resultCode'] > 0:
        msg = json_response.get('resultCodeMessage') or json_response.get('resultCodeDesc') or "Unknown error!"
        raise Exception(msg)
    del json_response['resultCode']

